<?php
/** RAG: why retrieval, chunking, embeddings and vector databases (pgvector), building the prompt, evaluation and improvements. */

return [
    'id' => 'rag', 'family' => 'llm', 'after' => 'llm-api',
    'title' => L('RAG ed embedding', 'RAG and Embeddings'), 'short' => L('RAG', 'RAG'), 'level' => L('Avanzato', 'Advanced'),
    'desc' => L('Far rispondere un modello sui tuoi documenti: suddivisione in blocchi, embedding, database vettoriali con pgvector, costruzione del prompt, citazioni e valutazione.', 'Making a model answer from your documents: chunking, embeddings, vector databases with pgvector, building the prompt, citations and evaluation.'),
    'lessons' => [
        lesson('why', L('Perché RAG', 'Why RAG'), [
            P('Un LLM non conosce i tuoi documenti interni né i fatti dopo la sua data di taglio. **RAG** (Retrieval-Augmented Generation) risolve così: alla domanda, si **cercano** i passaggi rilevanti nei tuoi documenti e li si mettono nel prompt; il modello risponde **basandosi su quelli**.', 'An LLM does not know your internal documents or facts after its cutoff. **RAG** (Retrieval-Augmented Generation) fixes it like this: on a question, you **retrieve** the relevant passages from your documents and put them in the prompt; the model answers **based on them**.'),
            C('domanda ──► cerca nei documenti ──► 5 passaggi rilevanti
                                         │
prompt = istruzioni + passaggi + domanda ──► LLM ──► risposta con citazioni', 'text'),
            P('Vantaggi: fatti aggiornati senza riaddestrare, risposte verificabili con le fonti, meno allucinazioni. Se i documenti sono pochi e brevi, a volte basta metterli tutti nel contesto, senza ricerca.', 'Advantages: up-to-date facts without retraining, answers verifiable through sources, fewer hallucinations. If the documents are few and short, sometimes you can put them all in the context, no search needed.'),
        ], [
            Q('w1', L('Che cosa fa la “R” di RAG?', 'What does the “R” in RAG do?'), [L('Cerca i passaggi rilevanti', 'Retrieves the relevant passages'), L('Riaddestra il modello', 'Retrains the model'), L('Riavvia il server', 'Restarts the server'), L('Riduce il prompt', 'Reduces the prompt')], 0, L('Retrieval.', 'Retrieval.')),
            Q('w2', L('Qual è un vantaggio di RAG sul fine-tuning per i fatti?', 'What is an advantage of RAG over fine-tuning for facts?'), [L('Si aggiorna cambiando i documenti', 'It updates by changing documents'), L('Non serve nessun documento', 'No documents needed'), L('Costa sempre di più', 'It always costs more'), L('Rende il modello più grande', 'It makes the model bigger')], 0, L('Niente riaddestramento.', 'No retraining.')),
            Q('w3', L('Quando si può fare a meno della ricerca?', 'When can you skip retrieval?'), [L('Se i documenti stanno tutti nel contesto', 'If all documents fit in the context'), L('Mai', 'Never'), L('Se i documenti sono milioni', 'If there are millions of documents'), L('Se il modello è piccolo', 'If the model is small')], 0, L('La soluzione più semplice prima.', 'Simplest solution first.')),
        ], task('text', L('Metti in ordine i passi di RAG, uno per riga numerata da `1.` a `4.`: genera la risposta, cerca i passaggi, ricevi la domanda, costruisci il prompt.', 'Order the RAG steps, one per line numbered `1.` to `4.`: generate the answer, retrieve passages, receive the question, build the prompt.'), '', [re('^1\.\s*(ricevi|receive)', L('Prima la domanda', 'Question first')), re('^2\.\s*(cerca|retrieve)', L('Poi la ricerca', 'Then retrieval')), re('^3\.\s*(costruisci|build)', L('Poi il prompt', 'Then the prompt')), re('^4\.\s*(genera|generate)', L('Infine la risposta', 'Finally the answer'))], '', "1. ricevi la domanda\n2. cerca i passaggi\n3. costruisci il prompt\n4. genera la risposta"), [
            dMatch(pMatch(), [['Retrieval', L('Trovare i passaggi', 'Finding passages')], ['Augmented', L('Aggiungerli al prompt', 'Adding them to the prompt')], ['Generation', L('Scrivere la risposta', 'Writing the answer')], [L('Citazione', 'Citation'), L('Fonte verificabile', 'Verifiable source')]], L('Le tre lettere di RAG.', 'RAG’s three letters.')),
            dFlash(pFlash(), [[L('RAG riduce le allucinazioni', 'RAG reduces hallucinations'), true], [L('RAG richiede di riaddestrare il modello', 'RAG requires retraining the model'), false], [L('Con RAG si possono citare le fonti', 'With RAG you can cite sources'), true], [L('RAG funziona solo con documenti pubblici', 'RAG only works with public documents'), false]], L('Documenti giusti, risposte giuste.', 'Right documents, right answers.')),
        ]),
        lesson('chunking', L('Suddividere i documenti', 'Chunking documents'), [
            P('I documenti si dividono in **blocchi** (chunk) di qualche centinaio di token: abbastanza grandi da avere senso da soli, abbastanza piccoli da essere precisi. Una piccola **sovrapposizione** tra blocchi evita di spezzare un concetto a metà.', 'Documents are split into **chunks** of a few hundred tokens: big enough to make sense on their own, small enough to be precise. A small **overlap** between chunks avoids cutting a concept in half.'),
            C('def blocchi(testo, dimensione=800, sovrapposizione=100):
    passo = dimensione - sovrapposizione
    return [testo[i:i + dimensione] for i in range(0, len(testo), passo)]

# meglio ancora: dividere per titoli e paragrafi, e salvare con ogni blocco
# i metadati: documento, sezione, pagina, data', 'python'),
            P('Dividere seguendo la struttura (titoli, paragrafi, articoli di un regolamento) funziona meglio che tagliare a caratteri. I **metadati** (titolo, pagina, data) servono per filtrare e per citare.', 'Splitting along the structure (headings, paragraphs, articles of a regulation) works better than cutting by characters. **Metadata** (title, page, date) help filter and cite.'),
        ], [
            Q('c1', L('Perché aggiungere sovrapposizione tra blocchi?', 'Why add overlap between chunks?'), [L('Per non spezzare un concetto a metà', 'To avoid cutting a concept in half'), L('Per occupare più spazio', 'To use more space'), L('Per confondere la ricerca', 'To confuse search'), L('Non serve', 'It is useless')], 0, L('Il contesto attraversa il taglio.', 'Context crosses the cut.')),
            Q('c2', L('Qual è il modo migliore di dividere un manuale?', 'What is the best way to split a manual?'), [L('Per titoli e paragrafi', 'By headings and paragraphs'), L('Ogni 10 caratteri', 'Every 10 characters'), L('A caso', 'At random'), L('Un blocco unico gigante', 'One giant chunk')], 0, L('Segui la struttura.', 'Follow the structure.')),
            Q('c3', L('A che cosa servono i metadati?', 'What is metadata for?'), [L('Filtrare e citare le fonti', 'Filtering and citing sources'), L('Colorare il testo', 'Colouring text'), L('Aumentare i token', 'Increasing tokens'), L('Niente', 'Nothing')], 0, L('Documento, pagina, data.', 'Document, page, date.')),
        ], task('python', L('Completa la funzione `blocchi`: con `passo = dimensione - sovrapposizione`, restituisci la lista `[testo[i:i + dimensione] for i in range(0, len(testo), passo)]`.', 'Complete the `blocchi` function: with `passo = dimensione - sovrapposizione`, return the list `[testo[i:i + dimensione] for i in range(0, len(testo), passo)]`.'), "def blocchi(testo, dimensione=800, sovrapposizione=100):\n    ", [re('passo\s*=\s*dimensione\s*-\s*sovrapposizione', L('Calcoli il passo', 'You compute the step')), re('return\s+\[\s*testo\s*\[\s*i\s*:\s*i\s*\+\s*dimensione\s*\]\s+for\s+i\s+in\s+range\s*\(\s*0\s*,\s*len\s*\(\s*testo\s*\)\s*,\s*passo\s*\)\s*\]', L('Restituisci i blocchi', 'You return the chunks'))], '', "passo = dimensione - sovrapposizione\n    return [testo[i:i + dimensione] for i in range(0, len(testo), passo)]"), [
            dMatch(pMatch(), [[L('Blocco', 'Chunk'), L('Pezzo di documento', 'Piece of document')], [L('Sovrapposizione', 'Overlap'), L('Testo condiviso tra blocchi', 'Text shared between chunks')], [L('Metadati', 'Metadata'), L('Titolo, pagina, data', 'Title, page, date')], [L('Struttura', 'Structure'), L('Titoli e paragrafi', 'Headings and paragraphs')]], L('Tagliare bene.', 'Cutting well.')),
            dFlash(pFlash(), [[L('Blocchi enormi rendono la ricerca meno precisa', 'Huge chunks make search less precise'), true], [L('Blocchi di 3 parole sono l’ideale', '3-word chunks are ideal'), false], [L('I metadati aiutano a citare', 'Metadata helps citing'), true], [L('Tagliare a caso è meglio che seguire i titoli', 'Cutting at random beats following headings'), false]], L('Il blocco giusto, al posto giusto.', 'The right chunk, in the right place.')),
        ]),
        lesson('vectors', L('Embedding e database vettoriali', 'Embeddings and vector databases'), [
            P('Ogni blocco viene trasformato in un **embedding** da un modello apposito e salvato in un **database vettoriale**. Alla domanda, si calcola il suo embedding e si cercano i blocchi più vicini (similarità del coseno). Se usi già PostgreSQL, l’estensione **pgvector** basta per iniziare.', 'Each chunk is turned into an **embedding** by a dedicated model and saved in a **vector database**. On a question, you compute its embedding and find the closest chunks (cosine similarity). If you already use PostgreSQL, the **pgvector** extension is enough to start.'),
            C('CREATE EXTENSION vector;
CREATE TABLE blocchi (
    id BIGSERIAL PRIMARY KEY,
    documento TEXT,
    testo TEXT,
    embedding vector(1024)
);
CREATE INDEX ON blocchi USING hnsw (embedding vector_cosine_ops);

-- i 5 blocchi più vicini alla domanda ($1 = embedding della domanda)
SELECT documento, testo FROM blocchi
ORDER BY embedding <=> $1
LIMIT 5;', 'sql'),
            P('`<=>` è la distanza del coseno (più piccola = più simile). L’indice **HNSW** rende veloce la ricerca anche su milioni di blocchi. Spesso si combina con la ricerca per parole chiave (**ricerca ibrida**), che trova nomi e codici esatti.', '`<=>` is cosine distance (smaller = more similar). The **HNSW** index makes search fast even over millions of chunks. It is often combined with keyword search (**hybrid search**), which finds exact names and codes.'),
        ], [
            Q('v1', L('Che cosa misura `<=>` in pgvector?', 'What does `<=>` measure in pgvector?'), [L('La distanza del coseno', 'Cosine distance'), L('L’uguaglianza esatta', 'Exact equality'), L('La lunghezza del testo', 'Text length'), L('La data', 'The date')], 0, L('Più piccola, più simile.', 'Smaller, more similar.')),
            Q('v2', L('A che cosa serve l’indice HNSW?', 'What is the HNSW index for?'), [L('Ricerca veloce dei vettori vicini', 'Fast nearest-vector search'), L('Ordinare per data', 'Sorting by date'), L('Cifrare i dati', 'Encrypting data'), L('Comprimere il testo', 'Compressing text')], 0, L('Approssimata ma rapidissima.', 'Approximate but very fast.')),
            Q('v3', L('Che cos’è la ricerca ibrida?', 'What is hybrid search?'), [L('Vettori più parole chiave', 'Vectors plus keywords'), L('Ricerca su due server', 'Search on two servers'), L('Ricerca a voce', 'Voice search'), L('Ricerca senza indice', 'Search without an index')], 0, L('Trova anche codici e nomi esatti.', 'It also finds exact codes and names.')),
        ], task('sql', L('Scrivi la query che restituisce `testo` dei 3 blocchi più vicini all’embedding `$1`, ordinando con `<=>`.', 'Write the query returning `testo` of the 3 chunks closest to embedding `$1`, ordering with `<=>`.'), '', [re('SELECT\s+testo\s+FROM\s+blocchi', L('Leggi i blocchi', 'You read the chunks')), re('ORDER\s+BY\s+embedding\s*<=>\s*\$1', L('Ordini per distanza', 'You order by distance')), re('LIMIT\s+3', L('Ne prendi 3', 'You take 3'))], '', "SELECT testo FROM blocchi ORDER BY embedding <=> \$1 LIMIT 3;"), [
            dBlanks(pFill(), "CREATE EXTENSION ___;\nCREATE TABLE doc (id SERIAL, testo TEXT, e ___(768));\nSELECT testo FROM doc ORDER BY e ___ $1 LIMIT 5;", ['vector', 'vector', '<=>'], ['pgai', 'array', '<>'], L('pgvector in tre righe.', 'pgvector in three lines.')),
            dOrder(pSort(), [L('Calcola l’embedding di ogni blocco', 'Compute each chunk’s embedding'), L('Salvalo nel database vettoriale', 'Store it in the vector database'), L('Calcola l’embedding della domanda', 'Compute the question’s embedding'), L('Cerca i blocchi più vicini', 'Find the closest chunks')], L('Indicizzare, poi cercare.', 'Index, then search.')),
        ]),
        lesson('prompt', L('Costruire il prompt', 'Building the prompt'), [
            P('I blocchi trovati vanno nel prompt in modo ordinato, ognuno con la sua fonte. Le istruzioni devono dire di rispondere **solo** in base ai documenti, di **citare** le fonti e di dire chiaramente quando la risposta non c’è.', 'The retrieved chunks go into the prompt in an orderly way, each with its source. The instructions must say to answer **only** from the documents, to **cite** the sources and to say clearly when the answer is not there.'),
            C('Rispondi alla domanda usando solo i documenti qui sotto.
Cita la fonte tra parentesi quadre, es. [regolamento.pdf, p. 4].
Se i documenti non contengono la risposta, scrivi: “Non trovo la risposta nei documenti.”

<documenti>
<doc fonte="regolamento.pdf, p. 4">Le ferie vanno richieste con 15 giorni di anticipo…</doc>
<doc fonte="faq.md">Le richieste si inviano dal portale HR…</doc>
</documenti>

Domanda: con quanto anticipo devo chiedere le ferie?', 'text'),
            P('Metti i documenti **prima** della domanda, separali con tag e non esagerare: troppi blocchi poco pertinenti confondono il modello e costano token.', 'Put the documents **before** the question, separate them with tags and do not overdo it: too many barely relevant chunks confuse the model and cost tokens.'),
        ], [
            Q('p1', L('Che cosa deve fare il modello se la risposta non è nei documenti?', 'What should the model do if the answer is not in the documents?'), [L('Dirlo chiaramente', 'Say so clearly'), L('Inventarla', 'Make it up'), L('Rispondere a un’altra domanda', 'Answer another question'), L('Non rispondere mai più', 'Never answer again')], 0, L('Meglio “non lo so” che un’invenzione.', 'Better “I don’t know” than a fabrication.')),
            Q('p2', L('Perché indicare la fonte di ogni blocco?', 'Why give each chunk’s source?'), [L('Per poter citare e verificare', 'To be able to cite and verify'), L('Per allungare il prompt', 'To lengthen the prompt'), L('Per il copyright del modello', 'For the model’s copyright'), L('Non serve', 'It is not needed')], 0, L('L’utente può controllare.', 'The user can check.')),
            Q('p3', L('Che cosa succede con troppi blocchi poco pertinenti?', 'What happens with too many barely relevant chunks?'), [L('Il modello si confonde e si spende di più', 'The model gets confused and costs rise'), L('La risposta migliora sempre', 'The answer always improves'), L('Niente', 'Nothing'), L('Il database si cancella', 'The database is deleted')], 0, L('Qualità prima della quantità.', 'Quality over quantity.')),
        ], task('text', L('Scrivi le istruzioni di un prompt RAG che: usa **solo** i documenti, **cita** la fonte e dice “Non trovo la risposta nei documenti” quando manca.', 'Write the instructions of a RAG prompt that: uses **only** the documents, **cites** the source and says “Non trovo la risposta nei documenti” when it is missing.'), '', [re('solo|only', L('Solo i documenti', 'Only the documents')), re('cit|fonte|source', L('Chiedi le citazioni', 'You ask for citations')), re('Non trovo la risposta nei documenti', L('Gestisci la risposta mancante', 'You handle the missing answer'))], '', 'Rispondi usando solo i documenti forniti e cita la fonte tra parentesi quadre. Se i documenti non contengono la risposta, scrivi: “Non trovo la risposta nei documenti.”'), [
            dOrder(pSort(), [L('Istruzioni', 'Instructions'), L('<documenti> con le fonti', '<documents> with sources'), L('Domanda dell’utente', 'User question')], L('L’ordine del prompt RAG.', 'The RAG prompt order.')),
            dFlash(pFlash(), [[L('Conviene mettere i documenti prima della domanda', 'Documents should come before the question'), true], [L('Più blocchi sono sempre meglio', 'More chunks are always better'), false], [L('Il modello deve poter dire che la risposta manca', 'The model must be able to say the answer is missing'), true], [L('Le fonti si possono omettere', 'Sources can be omitted'), false]], L('Un buon prompt RAG.', 'A good RAG prompt.')),
        ]),
        lesson('evaluate', L('Valutare e migliorare', 'Evaluating and improving'), [
            P('Un sistema RAG può sbagliare in due punti: la **ricerca** (non trova il blocco giusto) o la **generazione** (lo trova ma risponde male). Si valutano separatamente: per la ricerca, il blocco giusto è tra i primi *k*? Per la risposta, è **fedele** ai documenti e **pertinente** alla domanda?', 'A RAG system can fail at two points: **retrieval** (it does not find the right chunk) or **generation** (it finds it but answers badly). Evaluate them separately: for retrieval, is the right chunk in the top *k*? For the answer, is it **faithful** to the documents and **relevant** to the question?'),
            P('Miglioramenti tipici: un **reranker** che riordina i risultati con un modello più preciso, la ricerca ibrida, riscrivere la domanda prima di cercare, filtri sui metadati (reparto, data), blocchi migliori. Cambia una cosa alla volta e misura con lo stesso insieme di domande.', 'Typical improvements: a **reranker** reordering results with a more precise model, hybrid search, rewriting the question before searching, metadata filters (department, date), better chunks. Change one thing at a time and measure with the same set of questions.'),
            C('domanda                                  blocco atteso        trovato nei primi 5?
“Anticipo per le ferie?”                 regolamento p.4      ✓
“Rimborso km auto propria?”              rimborsi.pdf p.2     ✗ → aggiungi ricerca ibrida', 'text'),
        ], [
            Q('e1', L('Quali sono i due punti di errore di RAG?', 'What are RAG’s two failure points?'), [L('Ricerca e generazione', 'Retrieval and generation'), L('Tastiera e mouse', 'Keyboard and mouse'), L('Server e client', 'Server and client'), L('Token e byte', 'Tokens and bytes')], 0, L('Vanno valutati separatamente.', 'They must be evaluated separately.')),
            Q('e2', L('Che cosa fa un reranker?', 'What does a reranker do?'), [L('Riordina i risultati con un modello più preciso', 'Reorders results with a more precise model'), L('Cancella i documenti', 'Deletes documents'), L('Traduce la domanda', 'Translates the question'), L('Aumenta i blocchi', 'Increases chunks')], 0, L('Prima ampio, poi preciso.', 'Broad first, then precise.')),
            Q('e3', L('Che cosa significa risposta “fedele”?', 'What does a “faithful” answer mean?'), [L('Basata solo sui documenti', 'Based only on the documents'), L('Molto lunga', 'Very long'), L('Scritta in rima', 'Written in rhyme'), L('Data velocemente', 'Given quickly')], 0, L('Niente aggiunte inventate.', 'No invented additions.')),
        ], task('text', L('Proponi due miglioramenti per un RAG che non trova i codici prodotto esatti, uno per riga che inizia con `-`.', 'Suggest two improvements for a RAG that cannot find exact product codes, one per line starting with `-`.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due proposte', 'Two proposals')), re('ibrid|hybrid|parole chiave|keyword|BM25|full.?text', L('Una riguarda la ricerca per parole chiave', 'One is about keyword search'))], '', "- aggiungere la ricerca ibrida con parole chiave\n- filtrare per metadati come categoria del prodotto"), [
            dMatch(pMatch(), [['Reranker', L('Riordina i risultati', 'Reorders results')], [L('Ricerca ibrida', 'Hybrid search'), L('Vettori + parole chiave', 'Vectors + keywords')], [L('Fedeltà', 'Faithfulness'), L('Risposta basata sui documenti', 'Answer grounded in documents')], [L('Top-k', 'Top-k'), L('Il blocco giusto è tra i primi', 'The right chunk is near the top')]], L('Misurare un RAG.', 'Measuring a RAG.')),
            dFlash(pFlash(), [[L('Ricerca e generazione vanno valutate separatamente', 'Retrieval and generation must be evaluated separately'), true], [L('Conviene cambiare tutto insieme', 'Better change everything at once'), false], [L('I filtri sui metadati possono aiutare', 'Metadata filters can help'), true], [L('Se la ricerca sbaglia, la risposta sarà comunque giusta', 'If retrieval fails, the answer will still be right'), false]], L('Un pezzo alla volta.', 'One piece at a time.')),
        ]),
    ],
];
